# Deterministic test ----
## Setup ----
# Load necessary data for the integration test
load(testthat::test_path("fixtures", "integration_test_data.RData"))

# Set the iteration ID to 1 for accessing specific input/output list
iter_id <- 1

# Extract model input and output data for the specified iteration
om_input <- om_input_list[[iter_id]]
om_output <- om_output_list[[iter_id]]
em_input <- em_input_list[[iter_id]]

modified_parameters <- readRDS(test_path("fixtures", "parameters_model_comparison_project.RDS"))

log_recruits_true <- matrix(c(t(om_output[["N.age"]])),
  om_input[["nyr"]], om_input[["nages"]],
  byrow = TRUE
)[, 1] |> log()

modified_parameters <- modified_parameters |>
    dplyr::rows_delete(
      tibble::tibble(
        module_name = "Recruitment",
        label = "log_devs"
      ),
      by = c("module_name", "label")
    ) |>
    dplyr::rows_append(
       tibble::tibble(
        module_name = "Recruitment",
        module_type = "BevertonHolt",
        label = "log_r",
        timing = 1:30,
        value = log_recruits_true,
        estimation_status = "random_effects",
        distribution_type = "process",
        distribution = "Dnorm"
      )
    )

## IO correctness ----
test_that("deterministic test of fims with recruitment log_r re", {
  result <- setup_and_run_FIMS_with_wrappers(
    iter_id = iter_id,
    om_input_list = om_input_list,
    om_output_list = om_output_list,
    em_input_list = em_input_list,
    estimation_mode = FALSE,
    modified_parameters = modified_parameters
  )

  #' @description Test that the output from FIMS run matches the model comparison project OM values.
  verify_fims_deterministic(
    report = get_report(result),
    estimates = get_estimates(result),
    om_input = om_input_list[[iter_id]],
    om_output = om_output_list[[iter_id]],
    em_input = em_input_list[[iter_id]],
    use_fimsfit = TRUE
  )

  #' @description Test that the NLLs from FIMS match the "true" NLLs from the model comparison project.
  verify_fims_nll(
    report = get_report(result),
    om_input = om_input_list[[iter_id]],
    om_output = om_output_list[[iter_id]],
    em_input = em_input_list[[iter_id]],
    log_devs = FALSE
  )

  clear()
})

test_that("estimation test of fims with re on log_r using wrapper functions", {
  result <- setup_and_run_FIMS_with_wrappers(
    iter_id = iter_id,
    om_input_list = om_input_list,
    om_output_list = om_output_list,
    em_input_list = em_input_list,
    estimation_mode = TRUE,
    modified_parameters = modified_parameters
  )


  #' @description Test that the estimation run of FIMS with recruitment random effects matches the operating model values.
  validate_fims(
    report = get_report(result),
    estimates = get_estimates(result),
    om_input = om_input_list[[iter_id]],
    om_output = om_output_list[[iter_id]],
    em_input = em_input_list[[iter_id]],
    use_fimsfit = TRUE
  )

  clear()
})


